  CONSTRAINT fk_skill_relation_related_skill_id FOREIGN KEY (related_skill_id) REFERENCES skill (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_skill_relation_skill_relation_type_id FOREIGN KEY (skill_relation_type_id) REFERENCES skill_relation_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_skill_relation_related_skill_id (related_skill_id),
  INDEX idx_skill_relation_skill_relation_type_id (skill_relation_type_id)
);
