CREATE TABLE IF NOT EXISTS state_region (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  country_id UUID NOT NULL,
  subdivision_type_id UUID NOT NULL,
  subdivision_code STRING(10) NOT NULL,
  display_name STRING(150) NOT NULL,
  native_name STRING(150),
  name_i18n JSONB NOT NULL,
  gst_state_code STRING(2),
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_state_region PRIMARY KEY (id),
  CONSTRAINT uq_state_region_country_id_subdivision_code UNIQUE (country_id, subdivision_code),
  CONSTRAINT uq_state_region_country_id_id UNIQUE (country_id, id),
  CONSTRAINT ck_state_region_gst_code_format CHECK (gst_state_code IS NULL OR gst_state_code ~ '^[0-9]{2}$'),
  CONSTRAINT ck_state_region_name_i18n_en CHECK (name_i18n ? 'en'),
  CONSTRAINT fk_state_region_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_state_region_subdivision_type_id FOREIGN KEY (subdivision_type_id) REFERENCES subdivision_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_state_region_country_id_display_name (country_id, display_name) WHERE is_active,
  INDEX idx_state_region_subdivision_type_id (subdivision_type_id)
);
