CREATE TABLE IF NOT EXISTS tax_id_type (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  country_id UUID NOT NULL,
  tax_id_subject_id UUID NOT NULL,
  tax_id_checksum_id UUID NOT NULL,
  code STRING(40) NOT NULL,
  display_name STRING(150) NOT NULL,
  name_i18n JSONB NOT NULL,
  validation_regex STRING(500) NOT NULL,
  format_example STRING(60) NOT NULL,
  mask_pattern STRING(40),
  min_length INT2 NOT NULL,
  max_length INT2 NOT NULL,
  is_sensitive BOOL NOT NULL DEFAULT true,
  is_individual_identifier BOOL NOT NULL DEFAULT false,
  is_required_for_organisation BOOL NOT NULL DEFAULT false,
  is_api_verifiable BOOL NOT NULL DEFAULT false,
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_tax_id_type PRIMARY KEY (id),
  CONSTRAINT uq_tax_id_type_country_id_code UNIQUE (country_id, code),
  CONSTRAINT ck_tax_id_type_length_order CHECK (min_length <= max_length AND min_length > 0),
  CONSTRAINT ck_tax_id_type_individual_is_sensitive CHECK (NOT is_individual_identifier OR is_sensitive),
  CONSTRAINT ck_tax_id_type_code_format CHECK (code ~ '^[a-z0-9_]+$'),
  CONSTRAINT ck_tax_id_type_name_i18n_en CHECK (name_i18n ? 'en'),
  CONSTRAINT fk_tax_id_type_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_tax_id_type_tax_id_subject_id FOREIGN KEY (tax_id_subject_id) REFERENCES tax_id_subject (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_tax_id_type_tax_id_checksum_id FOREIGN KEY (tax_id_checksum_id) REFERENCES tax_id_checksum (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_tax_id_type_tax_id_subject_id (tax_id_subject_id),
  INDEX idx_tax_id_type_tax_id_checksum_id (tax_id_checksum_id)
);
