CREATE TABLE IF NOT EXISTS city (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  country_id UUID NOT NULL,
  state_region_id UUID,
  place_type_id UUID NOT NULL,
  time_zone_id UUID,
  geo_source_id UUID,
  display_name STRING(150) NOT NULL,
  ascii_name STRING(150) NOT NULL,
  native_name STRING(150),
  name_search STRING(150) AS (lower(ascii_name)) STORED NOT NULL,
  geoname_ref STRING(20),
  population INT8,
  latitude DECIMAL(9,6),
  longitude DECIMAL(9,6),
  city_tier INT2,
  is_metro BOOL NOT NULL DEFAULT false,
  is_popular BOOL NOT NULL DEFAULT false,
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_city PRIMARY KEY (id),
  CONSTRAINT uq_city_country_id_state_region_id_ascii_name UNIQUE (country_id, state_region_id, ascii_name),
  CONSTRAINT ck_city_latitude_range CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CONSTRAINT ck_city_longitude_range CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  CONSTRAINT ck_city_coordinate_pair CHECK ((latitude IS NULL) = (longitude IS NULL)),
  CONSTRAINT ck_city_geo_source_when_coordinates CHECK (latitude IS NULL OR geo_source_id IS NOT NULL),
  CONSTRAINT ck_city_tier_range CHECK (city_tier IS NULL OR city_tier BETWEEN 1 AND 3),
  CONSTRAINT ck_city_population_nonneg CHECK (population IS NULL OR population >= 0),
  CONSTRAINT fk_city_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_city_state_region_id FOREIGN KEY (state_region_id) REFERENCES state_region (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_city_place_type_id FOREIGN KEY (place_type_id) REFERENCES place_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_city_time_zone_id FOREIGN KEY (time_zone_id) REFERENCES time_zone (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_city_geo_source_id FOREIGN KEY (geo_source_id) REFERENCES geo_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_city_country_state FOREIGN KEY (country_id, state_region_id) REFERENCES state_region (country_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_city_country_id_ascii_name (country_id, ascii_name) WHERE state_region_id IS NULL,
  UNIQUE INDEX uq_city_geoname_ref (geoname_ref) WHERE geoname_ref IS NOT NULL,
  INVERTED INDEX idx_city_name_search (name_search gin_trgm_ops),
  INDEX idx_city_country_id_name_search (country_id, name_search) WHERE is_active,
  INDEX idx_city_state_region_id_display_name (state_region_id, display_name) WHERE is_active,
  INDEX idx_city_is_popular_country_id (is_popular, country_id) WHERE is_popular,
  INDEX idx_city_place_type_id (place_type_id),
  INDEX idx_city_time_zone_id (time_zone_id),
  INDEX idx_city_geo_source_id (geo_source_id)
);
