CREATE TABLE IF NOT EXISTS institution (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  institution_type_id UUID NOT NULL,
  country_id UUID NOT NULL,
  state_region_id UUID,
  city_id UUID,
  accreditation_status_id UUID,
  verification_status_id UUID NOT NULL,
  merged_into_institution_id UUID,
  canonical_name STRING(200) NOT NULL,
  name_search STRING(200) AS (lower(canonical_name)) STORED NOT NULL,
  short_name STRING(50),
  website_url STRING(500),
  ror_ref STRING(30),
  national_registry_ref STRING(50),
  established_year INT2,
  is_active BOOL NOT NULL DEFAULT true,
  CONSTRAINT pk_institution PRIMARY KEY (id),
  CONSTRAINT uq_institution_country_id_name_search UNIQUE (country_id, name_search),
  CONSTRAINT ck_institution_not_self_merge CHECK (merged_into_institution_id IS NULL OR merged_into_institution_id <> id),
  CONSTRAINT ck_institution_established_year_range CHECK (established_year IS NULL OR established_year BETWEEN 800 AND 2200),
  CONSTRAINT fk_institution_institution_type_id FOREIGN KEY (institution_type_id) REFERENCES institution_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_institution_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_institution_state_region_id FOREIGN KEY (state_region_id) REFERENCES state_region (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_institution_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_institution_accreditation_status_id FOREIGN KEY (accreditation_status_id) REFERENCES accreditation_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_institution_verification_status_id FOREIGN KEY (verification_status_id) REFERENCES verification_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_institution_merged_into_institution_id FOREIGN KEY (merged_into_institution_id) REFERENCES institution (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INVERTED INDEX idx_institution_name_search (name_search gin_trgm_ops),
  UNIQUE INDEX uq_institution_ror_ref (ror_ref) WHERE ror_ref IS NOT NULL,
  INDEX idx_institution_city_id (city_id),
  INDEX idx_institution_institution_type_id (institution_type_id),
  INDEX idx_institution_state_region_id (state_region_id),
  INDEX idx_institution_accreditation_status_id (accreditation_status_id),
  INDEX idx_institution_verification_status_id (verification_status_id),
  INDEX idx_institution_merged_into_institution_id (merged_into_institution_id)
);
